tmr1(IN := (s1steg = 1), PT := T#26s);
tmr2(IN := (s2steg = 1), PT := T#31s);
tpAck(IN := (s1steg = 4) AND NOT tpAck.Q, PT := T#500ms);
CASE s1steg OF
0:
IF ST250_PRT_PRS AND EMG_OK AND xDrift THEN
s1steg := 1;
END_IF;
1:
IF tmr1.Q AND EMG_OK AND xDrift THEN
s1steg := 2;
END_IF;
2:
IF xSlapp THEN
s1steg := 3;
END_IF;
3:
IF (NOT ST250_PRT_PRS) AND ST260_PRT_PRS AND (s2steg = 1) AND EMG_OK THEN
s1steg := 4;
END_IF;
4:
IF (NOT tpAck.Q) AND EMG_OK AND xDrift THEN
s1steg := 0;
END_IF;
ELSE
s1steg := 0;
END_CASE;
CASE s2steg OF
0:
IF xTaEmot AND ST260_PRT_PRS AND ST250_STA_DONE AND EMG_OK THEN
s2steg := 1;
END_IF;
1:
IF tmr2.Q AND EMG_OK AND xDrift THEN
s2steg := 2;
END_IF;
2:
IF (NOT ST260_PRT_PRS) AND EMG_OK THEN
s2steg := 0;
END_IF;
ELSE
s2steg := 0;
