        END_IF;
    3:
        IF xDrift AND ST560_RB_DONE AND ST560_DOR_OPENED AND NOT ST560_SPN_RUN THEN
            steg1 := 4;
        END_IF;
    4:
        IF xDrift AND ST560_CHK_CLAMPED THEN
            steg1 := 5;
        END_IF;
    5:
        IF xDrift AND NOT ST560_DOR_OPENED AND ST560_CHK_CLAMPED THEN
            steg1 := 6;
        END_IF;
    6:
        IF ST560_SPN_RUN THEN
            steg1 := 0;
        END_IF;
END_CASE;
(* machine 2 sequence *)
CASE steg2 OF
    0:
        IF xDrift AND ST570_CYC_DONE AND NOT ST570_SPN_RUN AND ST560_PRT_PRS AND NOT ST560_DOR_OPEN AND NOT ST560_DOR_OPENED AND (steg1 = 0 OR steg1 = 6) THEN
            steg2 := 1;
        END_IF;
    1:
        IF xDrift AND ST570_DOR_OPENED AND NOT ST570_SPN_RUN THEN
            steg2 := 2;
        END_IF;
    2:
        IF xDrift AND NOT ST570_CHK_CLAMPED AND ST570_DOR_OPENED AND NOT ST570_SPN_RUN AND (steg1 <> 3) THEN
            steg2 := 3;
        END_IF;
    3:
        IF xDrift AND ST560_RB_DONE AND ST570_DOR_OPENED AND NOT ST570_SPN_RUN THEN
            steg2 := 4;
        END_IF;
    4:
        IF xDrift AND ST570_CHK_CLAMPED THEN
            steg2 := 5;
        END_IF;
    5:
        IF xDrift AND NOT ST570_DOR_OPENED AND ST570_CHK_CLAMPED THEN
            steg2 := 6;
        END_IF;
    6:
        IF ST570_SPN_RUN THEN
            steg2 := 0;
        END_IF;
END_CASE;
(* robot ownership flags *)
xRobot1 := steg1 = 3;
xRobot2 := steg2 = 3;
(* outputs each driven once with interlock *)
ST560_DOR_OPEN := ((steg1 = 1 OR steg1 = 2 OR steg1 = 3 OR steg1 = 4) AND NOT ST560_SPN_RUN AND NOT ST570_DOR_OPEN AND NOT ST570_DOR_OPENED AND xDrift AND EMG_OK);
ST570_DOR_OPEN := ((steg2 = 1 OR steg2 = 2 OR steg2 = 3 OR steg2 = 4) AND NOT ST570_SPN_RUN AND NOT ST560_DOR_OPEN AND NOT ST560_DOR_OPENED AND xDrift AND EMG_OK);
ST560_CHK_CLAMP := NOT ((steg1 = 2 OR steg1 = 3) AND NOT ST560_SPN_RUN AND xDrift AND EMG_OK);
ST570_CHK_CLAMP := NOT ((steg2 = 2 OR steg2 = 3) AND NOT ST570_SPN_RUN AND xDrift AND EMG_OK);
ST560_CYC_START := (steg1 = 6) AND ST560_CHK_CLAMPED AND NOT ST560_SPN_RUN AND xDrift AND EMG_OK;
ST570_CYC_START := (steg2 = 6) AND ST570_CHK_CLAMPED AND NOT ST570_SPN_RUN AND xDrift AND EMG_OK;
ST560_RB_START := ((xRobot1 AND ST560_DOR_OPENED AND NOT ST560_SPN_RUN) OR (xRobot2 AND ST570_DOR_OPENED AND NOT ST570_SPN_RUN)) AND xDrift AND EMG_OK;
SYS_ALARM := xLarm;

trigReset(CLK:=SYS_RESET);
IF NOT EMG_OK THEN
  xKravOmstart := TRUE;
END_IF;
IF trigReset.Q AND EMG_OK THEN
  xKravOmstart := FALSE;
  xLarm := FALSE;
  steg := 0;
END_IF;
xDriftsklar := NOT xKravOmstart AND EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xLarm;
tmrAck(IN:=ST310_HSK_REQ AND NOT ST310_HSK_ACK, PT:=T#3s);
IF tmrAck.Q THEN
  xLarm := TRUE;
END_IF;
IF ST320_GRP_CLOSED AND (ST320_GRP_FRC < 40.0 OR ST320_GRP_FRC > 260.0) THEN
  xLarm := TRUE;
END_IF;
IF steg = 0 AND ST310_PRT_PRS AND xDriftsklar AND EMG_OK AND ST310_ZON_FREE THEN
  steg := 1;
ELSIF steg = 1 AND ST310_RB_DONE AND xDriftsklar AND EMG_OK THEN
  steg := 2;
ELSIF steg = 2 AND ST310_HSK_ACK AND xDriftsklar AND EMG_OK AND ST310_ZON_FREE THEN
  steg := 3;
ELSIF steg = 3 AND ST320_RB_DONE AND xDriftsklar AND EMG_OK THEN
  steg := 4;
ELSIF steg = 4 AND ST320_GRP_CLOSED AND xDriftsklar AND EMG_OK THEN
  steg := 5;
ELSIF steg = 5 AND ST310_GRP_OPENED AND ST310_HSK_DONE AND xDriftsklar AND EMG_OK THEN
  steg := 6;
ELSIF steg = 6 AND NOT ST310_HSK_ACK AND EMG_OK THEN
  steg := 0;
END_IF;
ST310_RB_START := (steg = 1) AND xDriftsklar AND EMG_OK AND ST310_ZON_FREE AND AIR_OK AND SYS_AUTO AND NOT xLarm AND NOT (steg = 3);
ST320_RB_START := (steg = 3) AND xDriftsklar AND EMG_OK AND ST310_ZON_FREE AND AIR_OK AND SYS_AUTO AND NOT xLarm AND NOT (steg = 1);
ST320_GRP_CLOSE := ((steg = 4) OR (steg = 5) OR (steg = 6)) AND EMG_OK AND NOT xLarm;
ST310_GRP_OPEN := ((steg = 5) OR (steg = 6)) AND ST320_GRP_CLOSED AND EMG_OK AND NOT xLarm;
ST310_HSK_REQ := ((steg = 2) OR (steg = 3) OR (steg = 4) OR (steg = 5)) AND EMG_OK AND NOT xLarm;
ST310_HSK_RST := (steg = 6) AND EMG_OK;
SYS_ALARM := xLarm;

trigReset(CLK:=SYS_RESET);
trigDone(CLK:=ST490_XFR_DONE);
IF NOT EMG_OK THEN
xKravOmstart:=TRUE;
ELSIF trigReset.Q AND EMG_OK THEN
xKravOmstart:=FALSE;
END_IF;
xDriftsklar:=EMG_OK AND SYS_AUTO AND NOT xKravOmstart AND NOT xLarm;
IF trigDone.Q THEN
xDoneSedd:=TRUE;
ELSIF steg=0 THEN
xDoneSedd:=FALSE;
END_IF;
CASE steg OF
0:
IF xDriftsklar AND ST490_XFR_REQ AND NOT ST490_PEC_IN AND ST490_DOK_OK THEN
steg:=1;
END_IF;
1:
IF xLarm THEN
steg:=0;
ELSIF ST490_PEC_IN AND xDoneSedd AND NOT ST490_PEC_GAP THEN
steg:=2;
END_IF;
2:
IF xLarm THEN
steg:=0;
ELSIF NOT ST490_XFR_REQ AND NOT ST490_XFR_DONE THEN
steg:=0;
END_IF;
END_CASE;
xXfrAktiv:=(steg=1);
tmrXfr(IN:=xXfrAktiv, PT:=T#4s);
IF trigReset.Q AND EMG_OK THEN
xLarm:=FALSE;
ELSIF tmrXfr.Q OR (ST490_PEC_IN AND (ST490_LOD_WGT < 10.0 OR ST490_LOD_WGT > 20.0)) THEN
xLarm:=TRUE;
END_IF;
ST490_XFR_ACK:=(steg=1) AND ST490_XFR_REQ AND NOT ST490_PEC_IN AND ST490_DOK_OK AND xDriftsklar AND NOT xLarm;
ST490_CNV_RUN:=(steg=1) AND ST490_XFR_REQ AND ST490_DOK_OK AND xDriftsklar AND NOT xLarm AND (NOT ST490_PEC_IN OR ST490_PEC_GAP);
ST490_XFR_RST:=(steg=2) AND xDoneSedd AND xDriftsklar AND NOT xLarm;
SYS_ALARM:=xLarm;
